select pg_temp.cr_identity();
do $cr_fixture$
declare refused boolean; actual_code text; actual_message text; returned jsonb; case_input jsonb; expected_value jsonb; expected_text text; item record;
begin
for item in select r.* from pg_temp.cr_render r where not exists(select 1 from pg_temp.cr_render_proof p where p.id=r.id)order by r.id loop
 case_input := item.raw_text::jsonb;
 if convert_to(case_input::text,'UTF8') is distinct from convert_to(item.expected_text,'UTF8') then raise exception 'record_fixture_renderer_mismatch: %',item.id;end if;
 if item.preimage_hash is not null and encode(sha256(convert_to(item.raw_text,'UTF8')),'hex')<>item.preimage_hash then raise exception 'record_fixture_preimage_hash_mismatch: %',item.id;end if;
end loop;

